[6641] = {"Vorsha la Azotadora", {"Mantén a salvo a Muglash en su viaje hacia el blandón. Ayúdalo a apagar el blandón y entonces protégelo frente a los nagas.","","Si sales airoso, vuelve a la Avanzada de Zoram'gar e informa al corredor Grito de Guerra sobre la muerte de Vorsha la Azotadora."}},
[6661] = {"A por las ratas del tren subterráneo", {"Captura a 5 ratas del subterráneo usando la flauta cazarratas. Guía a las ratas hasta Monty. No te olvides de devolver la flauta cuando hayas acabado."}},
[6662] = {"Mi hermano Nipsy", {"Lleva la caja de carne misteriosa a Niblis, que está en el Depósito del Tren Subterráneo de Ventormenta."}},
