[92708] = {"Una gran aventura", {"Escucha lo que quiere contarte Ayessa Cantoalba."}},
[92709] = {"Una gran aventura", {"Escucha lo que quiere contarte Elaadrin Vendaval del Atardecer en Valanaar."}},
[92727] = {"El erudito desaparecido", {"Descubre qué fue de Fillion Brisallama."}},
[92741] = {"Visitas inoportunas", {"Ve al Bosque Ventosombra y recoge 8 garfas de chilladora para Iaadaria Vientoamargo en Valanaar."}},
[92742] = {"Probar los pozos", {"Usa el equipo de muestras de agua de pozo para conseguir muestras de los pozos de la Finca de Jansen y la Granja de Molsen."}},
[92743] = {"Una corona para un conquistador", {"Mantén tu reputación con los Magram y lleva una corona de conquistador de las Tierras Inhóspitas a Warug al Poblado Magram."}},
[92744] = {"Branquias de múrloc", {"Alba Lunajusta quiere que consigas 7 branquias de múrloc de Playa Larga por la cosa de los Páramos de Poniente."}},
[92745] = {"El estado de las minas", {"Acaba con 4 cavadores kóbolds en la Mina de Jango y con 6 mineros Zarparrío en la Mina de la Costa del Oro."}},
[92747] = {"Espionaje en Arroyo de la Luna", {"Consigue 8 suministros industriales sospechosos en Arroyo de la Luna."}},
[92748] = {"Consultoría explosiva", {"Viaja al Distrito de los Enanos de Ventormenta y busca a algún ingeniero que pueda ayudarte."}},
[92749] = {"Un plan explosivo", {"Consigue 10 unidades de dinamita férrea mediante fabricación, comercio o en la casa de subastas y luego vuelve con Duendy Ruedadentada en el Distrito de los Enanos de Ventormenta."}},
[92750] = {"Detonación a distancia", {"Habla con alguien del servicio secreto de Ventormenta para conseguir un detonador a distancia."}},
[92751] = {"Detonación a distancia", {"Llévale el equipo de detonador a distancia a Duendy Ruedadentada en el Distrito de los Enanos de Ventormenta."}},
[92752] = {"Consultoría explosiva", {"Vuelve con Alba Lunajusta en los Páramos de Poniente."}},
[92753] = {"Destrucción en las Minas de la Muerte", {"Encuentra la forja oculta en las Minas de la Muerte y coloca los explosivos extradestructivos cerca. Luego, reúnete con Alba Lunajusta en la salida de las minas."}},
[92754] = {"Se necesita protección contra las Sombras", {"Mantén tu reputación con los Magram y lleva 3 pociones de protección contra las Sombras superiores a Mirda en el Poblado Magram de Desolace."}},
[92755] = {"Misticismo misterioso", {"Mantén tu reputación con los Gelkis y lleva 3 esencias místicas superiores a Halea en el Poblado Gelkis de Desolace."}},
[92811] = {"Guerra económica", nil},
[92812] = {"Guerra económica", nil},
[92814] = {"Necesito un sastre", {"Mantén tu reputación con los Gelkis y lleva una máscara de bandido blanca a Molkar en el Poblado Gelkis de Desolace."}},
[92817] = {"Maestría con el cuero", {"Mantén tu reputación con los Gelkis y lleva un arnés barbárico a Talra en el Poblado Gelkis de Desolace."}},
[92819] = {"Destrucción en las Minas de la Muerte", {"Utiliza el detonador."}},
[92834] = {"Venganza desmedida", {"Consigue 10 talismanes de piedra de viento de los cultores Al'Aketh que se encuentran al norte de Valanaar, en los campos de los Soplabayas o en el Santuario de Akir."}},
[92840] = {"Estudiar el viento", {"Lleva el Index Esoteria a las Piedras verticales del mirador de las Tierras Altas de Shen'dar y úsalo con las formaciones de piedras de viento de la zona para recopilar datos."}},
[92849] = {"El erudito desaparecido", {"Sigue buscando a Fillion Brisallama."}},
[92850] = {"El erudito desaparecido", {"Mata a la matriarca chilladora en su guarida y luego entrega su cabeza a Fillion Brisallama, en Valanaar."}},
