[92860] = {"Al servicio de Zephras", {"Informa a Valennia Puñotormenta y dile que la Orden Eminente la apoya en su lucha contra los Al'Aketh."}},
[92867] = {"Una tierra que proteger", {"Derrota a los intrusos Puño de Roca, de la Hermandad y de los Secacorteza en el Castillo de Stromgarde. Después, vuelve con el guardés Lomar."}},
[92871] = {"Al servicio de Zephras", {"Informa a Valennia Puñotormenta y dile que los Formavientos la apoyan en su lucha contra los Al'Aketh."}},
[92872] = {"Pasos obedientes", {"Lanza la faltriquera de polvo de tumba al Mare Magnum y vuelve a ver al cuidador Alaric en la cripta del Castillo de Stromgarde."}},
[92878] = {"Sin palabras", {"Lleva una prueba de la muerte de Namida Tótem Siniestro a Blaise Montgomery en el Campamento Mojache."}},
[92880] = {"Regreso a Valanaar", {"Llévale el informe de Yorna a Valennia Puñotormenta en Valanaar."}},
[92881] = {"La petición del sumo anciano", {"Ve a Valanaar y habla con Talaanis Cantosombrío."}},
[92909] = {"Cosechar a los cosechadores", {"Ozwin Ferropiñón, en la Granja de Saldean, quiere que le lleves 14 isomuelles de gólem y 5 giroestabilizadores de cosechador."}},
[92910] = {"Cosechar a los cosechadores", {"Llévale el chasis de autocognición precesiva a Ozwin Ferropiñón, en la Granja de Saldean."}},
[92911] = {"Cosechar a los cosechadores", {"Ozwin Ferropiñón, en la Granja de Saldean, quiere que le lleves 8 isomuelles de gólem, 4 moduladores de cobre y una mira rudimentaria."}},
[92914] = {"Pilones extraños", {"Explora Shen'dralas en busca de otros pilones como el que encontraste."}},
[92947] = {"Es nuestro turno", {"Acaba con 7 guardianes de Al'Aketh, 7 clamaespíritus de Al'Aketh y 7 maestros del acero de Al'Aketh, y luego informa a Hyusaa Brisa Presta en el Santuario de Akir."}},
[93034] = {"El Valle de los Huesos", {"Mejora tu reputación con los Gelkis y busca a Nerlokh cerca del Valle de los Huesos, al este del Poblado Gelkis."}},
[93036] = {"Infiltrarse en el culto", {"Habla con Sania Torrenteplata en la Aldea Shen'dar."}},
[93065] = {"Preparativos para la batalla", {"Habla con Valennia Puñotormenta en las Tierras Bajas de los Soplabayas."}},
[93089] = {"Lo que está por venir", {"Habla con Elaadrin Vendaval del Atardecer para partir de la Isla de Zephras."}},
[93090] = {"Lo que está por venir", {"Habla con Ayessa Cantoalba cuando estés preparada para marcharte de la Isla de Zephras."}},
[93159] = {"El ermitaño extraño", {"Habla con el ermitaño extraño en el Bosque Ventosombra y averigua más cosas sobre él."}},
[93160] = {"La recompensa del bosque", {"Recoge 8 bellotas ventosombra en el Bosque Ventosombra."}},
[93165] = {"La misericordia no existe", {"Consigue 5 orejas de cultores Al'Aketh en el Bosque Ventosombra, el Santuario de Akir o los Tierras Bajas de los Soplabayas."}},
[93172] = {"Libera a los huecos", {"Destruye 10 huecos ventosos en el Bosque Ventosombra."}},
[93176] = {"Amiguitos por doquier", {"Utilizando los objetos que contiene el kit de iniciación a la entomología, encuentra y atrapa un espécimen de tarántula arbórea, un gorgojo del heno y un recogedor de carne."}},
[93224] = {"Tótems de los centauros tallados", {"Consigue 5 tótems de los centauros tallados asesinando centauros de cualquier clan de Desolace y, luego, entrégaselos al capitán Pentigast en Punta de Nijel."}},
[93225] = {"Tótems de los centauros tallados", {"Consigue 5 tótems de los centauros tallados asesinando a centauros de cualquier clan de Desolace y, luego, entrégaselos a Gurda Ferocrín en el Campamento del Espíritu Errante."}},
[93226] = {"Amistad comprada: Magram", {"Lleva la bolsa de tótems al intendente de los Magram en el Poblado Magram de Desolace para aumentar considerablemente tu reputación con ese clan. Debes ser, como mínimo, Neutral con los Centauros del Clan Magram."}},
[93227] = {"Amistad comprada: Gelkis", {"Lleva la bolsa de tótems al intendente de los Gelkis en el Poblado Gelkis de Desolace para aumentar considerablemente tu reputación con ese clan. Debes ser, como mínimo, Neutral con los Centauros del Clan Gelkis."}},
[93317] = {"Temporada de cangrejo", {"Recoge 6 piezas de carne de reptador Canzalvaje."}},
[93318] = {"SE BUSCA: Vulgara el Insaciable", {"Mata a Vulgara el Insaciable en las Tierras Altas de Shen'dar y lleva su cabeza a Danarii Velobramido."}},
[93319] = {"Piedras de viento birladas", {"Quita 10 piedras de viento birladas a los bandidos de las Tierras Altas en las Tierras Altas de Shen'dar."}},
[93320] = {"Defender las torres", {"Preséntate ante Yorana Juncoventoso en la torre de vigilancia oriental de las Tierras Bajas de los Soplabayas."}},
[93429] = {"Sangre de mi sangre", {"Mata a 10 Perdidos en el Retiro Fangoso."}},
[93430] = {"Recuperar el cebo", {"Encuentra al pescador Perdido que ha robado el cebo de Pelluk y devuélveselo."}},
[93443] = {"El cajón de transporte perdido", {"Entrégale el cajón de transporte perdido a Friz Chispachás en Puerto Polvofusil, en Clarofluvial."}},
[93459] = {"Más orejas Al'Aketh", nil},
[93461] = {"La Aldea Shen'dar", {"Habla con Rathiril Lanzasol y Coriella Brisa Calmada en la Aldea Shen'dar."}},
[93464] = {"El mago visitante", {"Busca al mago en Desolace con conocimientos sobre el poder de la draenetista."}},
[93465] = {"Notas sobre la draenetista", {"Recoge las notas sobre la draenetista de Gimashi y llévaselas a Azore Aldamort."}},
[93552] = {"Cosecha de piedras de viento", {"Reúne 15 cúmulos de piedras de viento de las piedras de viento en bruto en la Arboleda Thendal."}},
[93644] = {"El diario ajado", {"El texto da a entender que el autor de este diario podría estar en algún lugar de Shen'dralas."}},
[93663] = {"Perdido en tránsito", {"Busca al mensajero perdido y asegúrate de que el envío de Dar llega al Puerto."}},
[93678] = {"Notas resumidas sobre la draenetista", {"Llévale las notas transcritas de Azore a Magtoor en el Puerto, en el Pantano de las Penas."}},
[93679] = {"Visiones de otro", {"Contempla la visión de Onku con Magtoor."}},
[93680] = {"La llave de la ciudad", {"Consigue la llave de las cloacas de Dalaran para el magus Wordeen Vacuamirada en Molino Tarren."}},
[93684] = {"El Encontrado", {"Encuentra al draenei que está buscando draenetista en las Tierras Devastadas."}},
