[93746] = {"Una respuesta firme", {"Planta cara a Belathaan Deseo Claro en el camino hacia el Santuario de Akir."}},
[93786] = {"Un mensaje sangriento", {"Asesina a 12 mozos de labranza de Campoarroyo y luego vuelve a hablar con Krom'rosh."}},
[93787] = {"Botín en la granja", {"Roba 6 bolsas para pienso de la granja de la Alianza en Campoarroyo y luego regresa con Krom'rosh."}},
[93788] = {"Hojas prestadas", {"Hazte con 10 hachas de leñador en el Aserradero de Turner y entrégaselas a Kreza Espinoscura en Rog'mar."}},
[93791] = {"Hablar con Belann", {"Habla con Belann Vientomadera en Valanaar."}},
[93797] = {"Ramas en el viento", {"Llévale una rama imbuida de viento a Belann Vientomadera en Valanaar."}},
