[93927] = {"Una última petición", {"Recoge la nota que has encontrado junto al pacificador y léela para decidir qué hacer a continuación."}},
[93948] = {"Entrega el sello", {"Entrega el sello de la familia Cantosombrío a Talaanis Cantosombrío en Valanaar."}},
[93949] = {"Vigilados", {"Mata saltanubes en Valanaar hasta que hayas eliminado 8 saltanubes encantados."}},
[93951] = {"Belleza de un plumazo", {"Reúne 8 plumas de hipogrifo en las Tierras Altas de Shen'dar."}},
[93958] = {"El Sagrario Interior", {"Habla con Valennia Puñotormenta en el Sagrario Interior del Santuario de Akir."}},
[93963] = {"Explorar la Alianza", {"Habla con Randal Emersonen el Castillo de Ventormenta para que te dé indicaciones. Úsalas para localizar al rey Magni Barbabronce, al manitas mayor Mekkatorque y a Tyrande Susurravientos y hablar con ellos."}},
[93976] = {"La comerciante goblin", {"Entrega la espada al contacto de Kreza Espinoscura en los muelles al este de Rog'mar."}},
[94003] = {"El baluarte Rompecielos", {"Arrebátale el baluarte Rompecielos a Zaal Escudo de Tormenta en el Santuario de Akir."}},
