[96403] = {"Reliquias importantes", {"Recupera 8 reliquias enanas en el Salón de los Feudales."}},
[96408] = {"Un visitante en Dun Morogh", {"Investiga el campamento sobre la Cantera de Gol'Bolar."}},
[96604] = {"El gran mundo exterior", {"Siéntate junto a la hoguera básica de Brakk y espera hasta recibir el beneficio Descanso mejorado."}},
[96605] = {"El gran mundo exterior", {"Siéntate junto a la hoguera básica de Kaga y espera hasta recibir el beneficio Descanso mejorado."}},
