[96638] = {"El aventurero", {"Habla con Raan Vientosalvaje cerca de la Aldea Shen'dar."}},
[96646] = {"Acampada para novatos: cocinar", {"Habla con Zerril Brisaleve en la Aldea Shen'dar y aprende a cocinar."}},
[96652] = {"El aventurero", {"Llévale el diario a Brakk cerca de Cerrotajo."}},
[96655] = {"Acampada para novatos: cocinar", {"Habla con el cocinero Torka en Cerrotajo para aprender a cocinar."}},
[96656] = {"La aventurera", {"Habla con Eleanor Tembleque cerca de Rémol."}},
[96658] = {"Acampada para novatos: cocinar", {"Habla con William Pickman en Rémol para aprender a cocinar."}},
