[97979] = {"La diosa provee", {"Lanza Luz de Elune y Fusión de las Sombras."}},
[97985] = {"Corazones atronadores", {"Mata a Corazón Atronador en Las Mil Agujas y consigue su corazón."}},
[98013] = {"Fuerzas henchidas", {"Elimina a 12 mirmidones Escama Tormentosa, 8 hechiceras Escama Tormentosa y 6 guerreros Escama Tormentosa para Arbal en el Páramo de los Ancianos."}},
[98021] = {"Viaje a la Colina del Centinela", {"Preséntate ante Gryan Mantorrecio en la Colina del Centinela, en los Páramos de Poniente."}},
[98024] = {"Viaje a El Cruce", {"Preséntate ante Thork en El Cruce de Los Baldíos."}},
[98025] = {"SE BUSCA: Jai'vhanel", {"Encuentra y mata al búho conocido como Jai'vhanel y llévate una de sus plumas. Lo vieron por última vez al norte de las ruinas de Ameth'Aran, cerca del pie de la montaña. Informa de la muerte de Jai'vhanel a la centinela Glynda Nal'Shea en Auberdine."}},
[98027] = {"El collar de media luna resplandeciente", {"Entrégale el collar de media luna a Maliynn en Astranaar."}},
[98028] = {"Barón Marinous", {"Llévale el globo de agua turbia a Onu en el Páramo de los Ancianos, en Costa Oscura."}},
[98042] = {"Todo son risas hasta que...", {"Consigue un ojo incomparable de un discípulo o un matón Crepuscular en la Espada del Maestro, en Costa Oscura. Después busca a alguien en Auberdine que esté dispuesto a hacerse cargo de él."}},
[98046] = {"La corona de la Tierra", {"Llévale el recipiente drenado a Lariia en el Templo de la Luna, en Darnassus."}},
[98059] = {"El tesoro de Trabalomas", {"Coloca la petición de compañía sellada sobre la mesa de contabilidad del ayuntamiento de Trabalomas."}},
[98065] = {"La corona de la Tierra", {"Lleva los restos de la poza de la luna a Tyrande Susurravientos en el Templo de la Luna, en Darnassus."}},
[98067] = {"Ojos de los centinelas", {"Coloca búhos centinela en la entrada que lleva a las profundidades del Fuerte Cenarion, en el Banco de Darnassus, en la posada del Bancal del Artesano y en la puerta de la ciudad para la centinela Dalia Filosol, que está en el Templo de la Luna de Darnassus."}},
[98069] = {"Los suministros de Viento Libre robados", {"Llévale 8 suministros de Viento Libre robados a Jandia en el Poblado Viento Libre."}},
[98070] = {"Silenciar el chirrido", {"Mata a 5 arpías estridentes, 5 arpías Malapluma estridentes y 5 arpías clamavientos estridentes."}},
[98071] = {"El oficio de cervecero", {"Entrega las botellas de varietales de Bajograjo en Dun Garok, que está al sureste de las Laderas de Trabalomas. Después, lleva de vuelta un saco de lúpulo de cerveza casera."}},
[98072] = {"Crocos del cielo", {"Consigue 8 escamas prístinas carmesíes y llévaselas a James Halloran en el Puerto de Menethil."}},
[98093] = {"Un campo que despejar", {"Sulhasa, en Los Baldíos del Sur, quiere que elimines a 7 lagartos tormenteros y a 7 acechadores Dentecenado en la zona para que pueda bajar del árbol sin peligro."}},
[98094] = {"Asistencia a los exploradores", {"La suma ejecutora Darthalia quiere que le entregues las nuevas órdenes al mortacechador Masoj, que se encuentra al sur de Molino Tarren, justo a las afueras de Dun Garok."}},
[98095] = {"Ventajas valiosas", {"El mortacechador Masoj necesita que coloques tres viales de apotecarios en los lugares claves de las Laderas de Trabalomas. Después, regresa con él."}},
[98155] = {"Las pelambres de pestillejo prístinas", {"Llévale 5 pelambres de pestillejo prístinas a Kristy Grant."}},
[98156] = {"Pelambres prístinas empaquetadas", {"Llévale el paquete de pelambres prístinas a Kimberly Grant."}},
[98189] = {"Devolver la Estatuilla", {"Lleva la Estatuilla de Menethil al capitán Puñorrecio en el Castillo de Menethil."}},
[98190] = {"Un amigo de la familia", {"Lleva la Estatuilla de Menethil al alto señor Bolvar Fordragón en el Castillo de Ventormenta."}},
[98191] = {"Un amigo de la familia", {"Lleva la Estatuilla de Menethil a Lord Grisillo Quiebrasombras en la Catedral de la Luz."}},
[98192] = {"Despellejar con cuidado y con destreza", {"Llévale 8 pellejos de raptor intactos a Krak en el Poblado Murohelecho."}},
[98197] = {"Botín de guerra", {"Recupera 6 trozos de madera de Khaz Modan y 30 fragmentos de hierro de Khaz Modan del Puerto de Menethil para Valstag Quijahierro."}},
[98205] = {"¡Las crías son lo peor!", {"Mata a 8 proles abrasadoras y a 8 crías abrasadoras."}},
[98208] = {"Flor de los cielos", {"Recupera la Nord'el para Sylessa Susurro del Anochecer en el Puerto de Menethil."}},
[98209] = {"Flor de los cielos", {"Lleva la Nord'el a Thundris Tejevientos en Auberdine, en Costa Oscura.","","Sylessa te ha recomendado que cojas un barco en el Puerto de Menethil que te llevará hasta allí."}},
[98215] = {"Escamas de dragón y colas chamuscadas", {"Llévale 20 escamas de dragón oscuras mudadas a Drazzit Gotera."}},
[98216] = {"Comprender el presente", {"Usa la piedra de Goaz cerca del guardián de Goaz y lleva la piedra angular titánica al prospector Whelgar."}},
