[98231] = {"Ingrediente activo", {"Llévale 10 colas de vermis a Gizzix Gluglú."}},
[98233] = {"La espada en el cieno", {"Recupera la espada de entrenamiento de Jameson y llévasela al guardia Jameson."}},
[98240] = {"Entrega de caja carmesí", {"Entrega la caja carmesí a Howin Plumamable cerca del camino que hay al este del Puerto de Menethil."}},
[98245] = {"Agujas de tajobuche", {"Consigue 10 incisivos de tajobuche para Howin Plumamable."}},
