[98247] = {"Etiqueta de envíos", {"Entrega la etiqueta de envíos a alguien de la sede comercial de la Autoridad Comercial de Azeroth en las Montañas Crestagrana."}},
[98248] = {"Etiqueta de envíos", {"Entrega la etiqueta de envíos a alguien del puesto comercial de Suministros y Logística de Durotar cerca de El Cruce, en Los Baldíos."}},
[98251] = {"No pienso volver", {"Mata 6 venados Necraste y 6 osos de Vallefresno y vuelve con Vax'ug Fuegoinquina al noroeste del Lago Cielo Estrellado."}},
