[98310] = {"La forja del futuro", {"Usa la piedra de Goaz cerca de Ados, Modr, Golm y Neru, y lleva sus corazones al prospector Whelgar."}},
[98313] = {"Un estudio más exhaustivo", {"Lleva el paquete de reliquias de Whelgar a Karnik el Historiador en Forjaz."}},
[98319] = {"Asegurar la montaña", {"Encuentra al montaraz Cornelius en El Cubil Pardo, como te ha pedido la montaraz Gretchen."}},
[98321] = {"Envío de Fuegosílex", {"Recoge 8 envíos de Fuegosílex en El Cubil Pardo para Tongus Fuegosílex, que está en Kharanos."}},
[98322] = {"Asegurar la montaña", {"Busca a la montaraz Gretchen al oeste de Kharanos."}},
[98323] = {"Asegurar la montaña", {"Lleva el informe de la montaraz Gretchen a Senir Barbablanca en Kharanos."}},
[98326] = {"Aúllaescarcha", {"Mata a Aúllaescarcha y consigue el saco de pescado para Gretta Ganter, en Las Birras."}},
